{
  "technical_and_design_decisions": [
    "Will support both Teradata JDBC driver directly (with NPE fix) and Hortonworks Connector integration for U1, with documentation updates",
    "For U2, will use Spring Boot's externalized configuration to make logging directory configurable via property override",
    "For U3/U5, will extract message-bus and serialization code into separate spring-bus module with proper Maven coordinates",
    "For U4, will refactor type conversion into spring-cloud-dataflow library with proper API boundaries",
    "For U6, will implement singlenode using ModuleLauncher with embedded admin and container in single JVM",
    "For U7, will implement Diego Receptor using Cloud Foundry APIs and Receptor client library",
    "For U8, will investigate Spring Cloud Service Discovery (Eureka/Consul) integration with Spring Cloud Stream module registration"
  ],
  "assumptions": [
    "Access to all required repositories (Spring XD, spring-bus, spring-cloud-dataflow, cloud-foundry-receptor) with appropriate permissions",
    "Existing test suites will be updated and maintained throughout development",
    "Development environment includes Java 17+ with Maven/Gradle build tools",
    "Teradata test environment available for U1 validation (or mock testing will be sufficient)",
    "Cloud Foundry Diego environment available for U7 testing (or will develop against APIs without deployment)",
    "Time allocated includes research, implementation, unit testing, and integration testing for each user story",
    "U8 investigation will produce a design document and prototype implementation",
    "All dependencies (Spring Framework 6.0+, etc.) are available in Maven repositories"
  ],
  "activities": [
    {
      "activity_id": "A1",
      "activity_name": "Analyze and fix Teradata JDBC connection NPE",
      "activity_description": "Investigate root cause of NPE when using Teradata JDBC driver directly. Implement fix for connection handling in Sqoop module. Update test cases for Teradata connectivity.",
      "most_likely_effort": 3.5
    },
    {
      "activity_id": "A2",
      "activity_name": "Integrate Hortonworks Connector for Teradata",
      "activity_description": "Add Maven dependency for Hortonworks Connector. Update Sqoop job definitions to support both driver options. Update documentation with configuration examples.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "A3",
      "activity_name": "Refactor logging configuration for U2",
      "activity_description": "Extract hardcoded logging directory (${xd.home}/logs) into configurable property. Update Logback/Log4j configuration. Create Spring Boot property override mechanism. Test with RPM installation paths.",
      "most_likely_effort": 2.5
    },
    {
      "activity_id": "A4",
      "activity_name": "Extract message-bus code to spring-bus for U3",
      "activity_description": "Identify message-bus components in Spring XD. Refactor code into standalone module. Update Spring XD Maven dependencies. Ensure backward compatibility. Update integration tests.",
      "most_likely_effort": 8
    },
    {
      "activity_id": "A5",
      "activity_name": "Extract type conversion to spring-cloud-dataflow for U4",
      "activity_description": "Identify input/output type conversion components. Refactor into spring-cloud-dataflow library. Update module API interfaces. Implement custom domain object support. Update tests.",
      "most_likely_effort": 6
    },
    {
      "activity_id": "A6",
      "activity_name": "Extract serialization codec to spring-bus for U5",
      "activity_description": "Identify serialization codec components. Refactor into spring-bus library alongside message-bus. Update serialization interfaces. Ensure compatibility with existing message formats. Test serialization scenarios.",
      "most_likely_effort": 5
    },
    {
      "activity_id": "A7",
      "activity_name": "Implement singlenode XD Admin SPI for U6",
      "activity_description": "Design singlenode architecture using ModuleLauncher. Implement embedded admin and container in single JVM. Create launch scripts/configuration. Develop comprehensive tests for local data pipelines. Documentation.",
      "most_likely_effort": 12
    },
    {
      "activity_id": "A8",
      "activity_name": "Implement Diego Receptor XD Admin SPI for U7",
      "activity_description": "Research Cloud Foundry Diego APIs. Implement Receptor client interface. Create Diego-specific module launcher. Handle CF container lifecycle. Develop test suite with mock CF environment. Deployment documentation.",
      "most_likely_effort": 14
    },
    {
      "activity_id": "A9",
      "activity_name": "Investigate Spring Cloud Stream service discovery for U8",
      "activity_description": "Research Spring Cloud Service Discovery options (Eureka, Consul). Prototype module registration mechanism. Develop proof-of-concept integration with Spring XD. Document findings and design recommendations.",
      "most_likely_effort": 5
    }
  ],
  "reported_total": {
    "most_likely_effort": 58
  }
}
